mapper.delete:
delete from MOD_STANDARD_GRADE_MAPPING
where GRADE_INST = #{gradeInst,jdbcType=VARCHAR}
and O_TYPE = #{oType,jdbcType=VARCHAR}

mapper.select:
select COUNT(1)
from MOD_STANDARD_GRADE_MAPPING
where 1=1

    AND  GRADE_INST = #{gradeInst,jdbcType=VARCHAR}


    AND  O_TYPE = #{oType,jdbcType=VARCHAR}


    AND  GRADE_RESULT = #{gradeResult,jdbcType=VARCHAR}

SELECT distinct A.GRADE_INST AS gradeInst, A.O_TYPE AS oType FROM MOD_STANDARD_GRADE_MAPPING A WHERE 1=1
AND GRADE_INST = #{gradeInst,jdbcType=VARCHAR}
AND O_TYPE = #{oType,jdbcType=VARCHAR}

SELECT A.SEQ_NO AS seqNo, A.GRADE_INST AS gradeInst, A.O_TYPE AS oType, A.GRADE_RESULT AS gradeResult, A.GRADE_STANDARD_RESULT AS gradeStandardResult, A.CREATE_USER AS createUser, A.CREATE_DEPT AS createDept, A.CREATE_TIME AS createTime, A.UPDATE_USER AS updateUser, A.UPDATE_TIME AS updateTime FROM MOD_STANDARD_GRADE_MAPPING A WHERE 1=1
AND GRADE_INST = #{gradeInst,jdbcType=VARCHAR}
AND O_TYPE = #{oType,jdbcType=VARCHAR}
